	}
	mes "-------------------";
	if (!.@card_break) {
		mes "Erosion of surface has not occurred during the card separation process.";
		mes "^0000ffCard separation has succeeded.^000000";
	} else {
		mes "Erosion of surface has occurred during the card separation process.";
		mes "Card has been damaged. ^ff0000Unrecoverable.^000000";
	}
	next;
	mes .@n$;
	mes "That is all for the results of the card separation. Please come again.";
	close;
