	mes "[Hypnotist]";
	mes "Although I offer unlimited";
	mes "stat/skill resets for now, I have";
	mes "two conditions that must be";
	mes "fulfilled. First, you must be";
	mes "lower than ^FF0000Base Level 50^000000.";
	next;
	mes "[Hypnotist]";
